    // So psi(n) = (10^k - 1) - n, where k is the number of digits of n.
    // Therefore, weight(n) = n * ((10^k - 1) - n).
    // This is a quadratic function in n: -n^2 + (10^k - 1) * n.
    // This quadratic is maximized at n = (10^k - 1) / 2.

    // So for each range of numbers with the same number of digits, the maximum 
    // of the quadratic occurs at the midpoint. We just need to check the 
    // closest integer to the midpoint that lies within [l, r] and has the 
    // same number of digits.

    // Let's iterate over possible digit lengths.
    // For each digit length k, the range of numbers is [10^(k-1), 10^k - 1].
    // We intersect this with [l, r].
    // For each such intersection, we find the optimal n.

    for (int k = 1; k <= 10; k++) {
        long long low = (k == 1) ? 1 : (long long)pow(10, k-1);
        long long high = (long long)pow(10, k) - 1;

        long long rangeLow = max(l, low);
        long long rangeHigh = min(r, high);

        if (rangeLow > rangeHigh) continue;

        // The quadratic n * ((10^k - 1) - n) is maximized at n = (10^k - 1) / 2.
        long long peak = (high) / 2;

        // Check candidates: peak, peak+1, and the boundaries of the intersection.
        long long candidates[] = {rangeLow, rangeHigh, peak, peak + 1};

        for (int i = 0; i < 4; i++) {
            long long n = candidates[i];
            if (n < rangeLow || n > rangeHigh) continue;
            long long psi = high - n;
            long long weight = n * psi;
            if (weight > maxWeight) {
                maxWeight = weight;
            }
        }
    }

    cout << maxWeight << endl;

    return 0;
}
